package com.pedroeu.ficha.data.content

import com.pedroeu.ficha.data.model.Feat
import com.pedroeu.ficha.data.model.Sourcebook

object FeatData {

    /** Feats granted by a background at character creation. */
    val ORIGIN_FEATS: List<Feat> = listOf(
        Feat("alert", "Alert", "You gain a bonus to Initiative equal to your Proficiency Bonus, and you can swap your Initiative with a willing ally's."),
        Feat("crafter", "Crafter", "You gain proficiency with three Artisan's Tools, get a 20% discount on nonmagical goods, and can craft items faster during a long rest."),
        Feat("healer", "Healer", "You can use a Healer's Kit as a Utilize action to restore hit points, and rerolling a 1 on any healing die is allowed."),
        Feat("lucky", "Lucky", "You have Luck Points equal to your Proficiency Bonus, which you can spend to gain Advantage on a d20 Test or impose Disadvantage on an attack against you."),
        Feat("magic_initiate_cleric", "Magic Initiate (Cleric)", "You learn two cantrips and one level 1 spell from the Cleric spell list. You can cast the level 1 spell once per long rest without a slot. Wisdom is your spellcasting ability for them."),
        Feat("magic_initiate_druid", "Magic Initiate (Druid)", "You learn two cantrips and one level 1 spell from the Druid spell list. You can cast the level 1 spell once per long rest without a slot. Wisdom is your spellcasting ability for them."),
        Feat("magic_initiate_wizard", "Magic Initiate (Wizard)", "You learn two cantrips and one level 1 spell from the Wizard spell list. You can cast the level 1 spell once per long rest without a slot. Intelligence is your spellcasting ability for them."),
        Feat("musician", "Musician", "You gain proficiency with three Musical Instruments, and after a rest you can grant Heroic Inspiration to allies equal to your Proficiency Bonus."),
        Feat("savage_attacker", "Savage Attacker", "Once per turn when you hit with a weapon, you can reroll the weapon's damage dice and use either total."),
        Feat("skilled", "Skilled", "You gain proficiency in any combination of three skills or tools of your choice."),
        Feat("tavern_brawler", "Tavern Brawler", "Your Unarmed Strike deals 1d4 damage, you can reroll a 1 on that die, and you can push a creature 5 feet once per turn."),
        Feat("tough", "Tough", "Your hit point maximum increases by twice your character level, and increases by 2 each time you gain a level."),

        // ---------------------------------- Eberron: Forge of the Artificer (Dragonmarks)
        // Every dragonmark feat requires an Eberron campaign and rules out any other mark.
        Feat("aberrant_dragonmark", "Aberrant Dragonmark", "Aberrant Fortitude: when you fail a Constitution saving throw you can take a Reaction to roll 1d4 and add it, once per Long Rest. Aberrant Magic: you know one cantrip and always have one level 1 spell prepared from the Sorcerer spell list, casting the spell free once per Short or Long Rest with Constitution as your spellcasting ability. Aberrant Surge: when you cast that spell you can expend a Hit Point Die — on an even roll you gain that many Temporary Hit Points, on an odd roll a creature within 30 feet takes that much Force damage.", Sourcebook.EBERRON),
        Feat("mark_of_detection", "Mark of Detection", "Deductive Intuition: add 1d4 to any Intelligence (Investigation) or Wisdom (Insight) check. Magical Detection: you always have Detect Magic and Detect Poison and Disease prepared and can cast each free once per Long Rest, adding See Invisibility at character level 3. Spells of the Mark adds Detect Evil and Good, Identify, Detect Thoughts, Find Traps, Clairvoyance, Nondetection, Arcane Eye, Divination, and Legend Lore to your class spell list.", Sourcebook.EBERRON),
        Feat("mark_of_finding", "Mark of Finding", "Hunter's Intuition: add 1d4 to any Wisdom (Perception or Survival) check. Finder's Magic: you always have Hunter's Mark prepared and can cast it free once per Long Rest, adding Locate Object at character level 3. Spells of the Mark adds Faerie Fire, Longstrider, Locate Animals or Plants, Mind Spike, Clairvoyance, Speak with Plants, Divination, Locate Creature, and Commune with Nature to your class spell list.", Sourcebook.EBERRON),
        Feat("mark_of_handling", "Mark of Handling", "Wild Intuition: add 1d4 to any Intelligence (Nature) or Wisdom (Animal Handling) check. Primal Connection: you always have Animal Friendship and Speak with Animals prepared and can cast each free once per Long Rest. Monstrous Connections: from character level 3 you can target a Monstrosity with an Intelligence of 3 or lower with those spells. Spells of the Mark adds Command, Find Familiar, Beast Sense, Calm Emotions, Beacon of Hope, Conjure Animals, Aura of Life, Dominate Beast, and Awaken.", Sourcebook.EBERRON),
        Feat("mark_of_healing", "Mark of Healing", "Medical Intuition: add 1d4 to any Wisdom (Medicine) check or check using a Herbalism Kit. Healing Touch: you always have Cure Wounds prepared and can cast it free once per Long Rest, adding Lesser Restoration at character level 3. Spells of the Mark adds False Life, Healing Word, Arcane Vigor, Prayer of Healing, Aura of Vitality, Mass Healing Word, Aura of Life, Aura of Purity, and Greater Restoration.", Sourcebook.EBERRON),
        Feat("mark_of_hospitality", "Mark of Hospitality", "Ever Hospitable: add 1d4 to any Charisma (Persuasion) check or check using Brewer's Supplies or Cook's Utensils. Innkeeper's Magic: you always have Purify Food and Drink and Unseen Servant prepared and can cast each free once per Long Rest, adding Calm Emotions at character level 3. Spells of the Mark adds Goodberry, Sleep, Aid, Enhance Ability, Create Food and Water, Leomund's Tiny Hut, Aura of Purity, Mordenkainen's Private Sanctum, and Hallow.", Sourcebook.EBERRON),
        Feat("mark_of_making", "Mark of Making", "Artisan's Intuition: add 1d4 to any Intelligence (Arcana) check or check using Artisan's Tools. Spellsmith: you know the Mending cantrip and always have Magic Weapon prepared, casting it free once per Long Rest. Spells of the Mark adds Identify, Tenser's Floating Disk, Continual Flame, Spiritual Weapon, Conjure Barrage, Elemental Weapon, Fabricate, Stone Shape, and Creation.", Sourcebook.EBERRON),
        Feat("mark_of_passage", "Mark of Passage", "Courier's Speed: your Speed increases by 5 feet. Intuitive Motion: add 1d4 to any Strength (Athletics) or Dexterity (Acrobatics) check. Magical Passage: you always have Misty Step prepared and can cast it free once per Long Rest. Spells of the Mark adds Expeditious Retreat, Jump, Find Steed, Pass without Trace, Blink, Phantom Steed, Dimension Door, Freedom of Movement, and Teleportation Circle.", Sourcebook.EBERRON),
        Feat("mark_of_scribing", "Mark of Scribing", "Gifted Scribe: add 1d4 to any Intelligence (History) check or check using Calligrapher's Supplies. Scribe's Insight: you know the Message cantrip and always have Comprehend Languages prepared, casting it free once per Long Rest and adding Magic Mouth at character level 3. Spells of the Mark adds Command, Illusory Script, Animal Messenger, Silence, Sending, Tongues, Arcane Eye, Confusion, and Dream.", Sourcebook.EBERRON),
        Feat("mark_of_sentinel", "Mark of Sentinel", "Sentinel's Intuition: add 1d4 to any Wisdom (Insight or Perception) check. Guardian's Shield: you always have the Shield spell prepared and can cast it free once per Long Rest. Vigilant Guardian: when a creature within 5 feet of you is hit by an attack roll, you can take a Reaction to swap places with it and be hit instead, a number of times equal to your Proficiency Bonus per Long Rest.", Sourcebook.EBERRON),
        Feat("mark_of_shadow", "Mark of Shadow", "Cunning Intuition: add 1d4 to any Dexterity (Stealth) or Charisma (Performance) check. Shape Shadows: you know the Minor Illusion cantrip and always have Invisibility prepared, casting it free once per Long Rest. Spells of the Mark adds Disguise Self, Silent Image, Darkness, Pass without Trace, Clairvoyance, Major Image, Greater Invisibility, Hallucinatory Terrain, and Mislead.", Sourcebook.EBERRON),
        Feat("mark_of_storm", "Mark of Storm", "Windwright's Intuition: add 1d4 to any Dexterity (Acrobatics) check or check using Navigator's Tools. Storm's Boon: you have Resistance to Lightning damage. Storm Magic: you know the Thunderclap cantrip, and from character level 3 you always have Gust of Wind prepared and can cast it free once per Long Rest.", Sourcebook.EBERRON),
        Feat("mark_of_warding", "Mark of Warding", "Warder's Intuition: add 1d4 to any Intelligence (Investigation) check or check using Thieves' Tools. Wards and Seals: you always have Alarm and Mage Armor prepared and can cast each free once per Long Rest, adding Arcane Lock at character level 3. Spells of the Mark adds Armor of Agathys, Sanctuary, Knock, Nystul's Magic Aura, Glyph of Warding, Magic Circle, Leomund's Secret Chest, Mordenkainen's Faithful Hound, and Antilife Shell.", Sourcebook.EBERRON),

        // ---------------------------------- Forgotten Realms: Heroes of Faerûn
        Feat("cult_of_the_dragon_initiate", "Cult of the Dragon Initiate", "Dragon's Tongue: you know Draconic, or another language if you already know it. Dragon's Terror: as a Magic action you can force a creature within 30 feet to succeed on a Wisdom saving throw (DC 8 plus your Wisdom modifier and Proficiency Bonus) or have the Frightened condition until the end of your next turn; on a success, or when the effect ends, it is immune for 24 hours. Inspired by Fear: when you cause a creature to be Frightened you can gain Heroic Inspiration if you lack it, once per Short or Long Rest.", Sourcebook.HEROES_OF_FAERUN),
        Feat("emerald_enclave_fledgling", "Emerald Enclave Fledgling", "Speak with Animals: you always have that spell prepared and can cast it with any spell slots you have, using Intelligence, Wisdom, or Charisma as your spellcasting ability; cast as a Ritual its duration is 8 hours. Tag Team: when you take the Help action you can switch places with a willing ally within 5 feet as part of the same action, without provoking Opportunity Attacks.", Sourcebook.HEROES_OF_FAERUN),
        Feat("harper_agent", "Harper Agent", "Thieves' Cant: you know Thieves' Cant. Instrument Training: you gain proficiency with a Musical Instrument of your choice. Distracting Melody: when you take the Help action to assist an ally's attack roll, the enemy you're distracting can be within 30 feet of you rather than 5 feet, provided it can see or hear you.", Sourcebook.HEROES_OF_FAERUN),
        Feat("lords_alliance_agent", "Lords' Alliance Agent", "Inspiring Strike: once per turn when you score a Critical Hit, you can choose an ally within 30 feet who can see or hear you and who lacks Heroic Inspiration; that ally gains it. Reassert Honor: when an enemy you can see deals damage to an ally within 5 feet of you, you have Advantage on your next attack roll against that enemy before the end of your next turn.", Sourcebook.HEROES_OF_FAERUN),
        Feat("purple_dragon_rook", "Purple Dragon Rook", "Entreat: you gain proficiency in Insight, Performance, or Persuasion. Rallying Cry: when you roll Initiative and don't have the Incapacitated condition, you can choose a number of creatures equal to your Proficiency Bonus within 30 feet of you, and those creatures gain Heroic Inspiration. Once you use this you can't do so again until you finish a Long Rest.", Sourcebook.HEROES_OF_FAERUN),
        Feat("spellfire_spark", "Spellfire Spark", "Magic Absorption: once per turn, when you take damage from a spell or magical effect, you reduce the total damage taken by 1d4, unless you have the Incapacitated condition. Spellfire Flame: you learn the Sacred Flame cantrip, using Intelligence, Wisdom, or Charisma as your spellcasting ability, and you can cast it as a Bonus Action a number of times equal to your Proficiency Bonus per Long Rest.", Sourcebook.HEROES_OF_FAERUN),
        Feat("tyro_of_the_gauntlet", "Tyro of the Gauntlet", "Stand as One: when an ally within 5 feet of you is subjected to an effect that would push or pull it, you can take a Reaction to prevent that movement, provided the ally doesn't have the Incapacitated condition. Vigilant: when you take the Ready action, the next attack roll made against you before the start of your next turn has Disadvantage.", Sourcebook.HEROES_OF_FAERUN),
        Feat("zhentarim_ruffian", "Zhentarim Ruffian", "Exploit Opening: when you roll damage for an Opportunity Attack, you can roll the damage dice twice and use either result. Family First: if you have Heroic Inspiration when you roll Initiative, you can expend it to give yourself and your allies Advantage on that Initiative roll.", Sourcebook.HEROES_OF_FAERUN),

        // ---------------------------------- Unearthed Arcana 2026: Villainous Options
        Feat("atoners_grace", "Atoner's Grace", "Disarming Mien: a creature's Hostile attitude doesn't impose Disadvantage on your Charisma (Persuasion) checks to influence that creature. Parley: when you take the Disengage or Influence action, each creature within 5 feet of you has Advantage on the next ability check or saving throw it makes before the start of your next turn.", Sourcebook.UA_VILLAINOUS),
        Feat("raised_by_cultists", "Raised by Cultists", "Bloody Revelation: when you become Bloodied, you can take a Reaction to gain Heroic Inspiration. Communal Caster: when an ally within 5 feet of you makes a Constitution saving throw to maintain Concentration, you can take a Reaction to give your ally Advantage on the save.", Sourcebook.UA_VILLAINOUS),
        Feat("trapper", "Trapper", "Eye for Detail: you have Advantage on any Intelligence (Investigation) check you make as part of the Study action. Swift Tracker: you don't have Disadvantage on Wisdom (Perception or Survival) checks while traveling at a Fast pace, and you have Advantage on such checks while traveling at a Normal pace. Trap Expert: you can take a Bonus Action, instead of a Utilize action, to set a Hunting Trap, and you add your Proficiency Bonus to the DC of the saving throw to avoid the trap and the DC of the check to escape it.", Sourcebook.UA_VILLAINOUS),
        Feat("underhanded", "Underhanded", "Elusive: immediately after you roll Initiative, you can move up to 10 feet. Fight Dirty: when a creature one size larger than you or smaller makes an Opportunity Attack against you and misses, you can take a Reaction to give that creature the Prone condition. You must have a free hand to use this Reaction.", Sourcebook.UA_VILLAINOUS),

        // ---------------------------------- Imported origin feats and Dark Gifts
        Feat("sharp_eye", "Sharp Eye", "When you take the Search or Study action, you can give yourself Advantage on any ability check made as part of that action. You can use this feature a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest. If the check fails, the use of this feature isn't expended.", Sourcebook.RAVENLOFT),
        Feat("survivor", "Survivor", "You gain the following benefits. Hypervigilance. Whenever you roll Initiative, you can reroll the d20 if the number rolled is 9 or lower. You must use the new roll. Steel Yourself. When you fail a saving throw to avoid or end the Charmed or Frightened condition, you can take a Reaction to add a bonus to the roll potentially causing it to succeed. The bonus is equal to your Proficiency Bonus. Once you take this Reaction, you can't do so again until you finish a Long Rest.", Sourcebook.RAVENLOFT),
        Feat("child_of_the_sun", "Child of the Sun", "You gain the following benefits. Eyes of Eirdu. You and allies within 10 feet of you have Advantage on saving throws made to avoid or end the Blinded condition. Faerie Fire. You learn the Faerie Fire spell. Intelligence, Wisdom, or Charisma is your spellcasting ability for this spell (choose when you select this feat). You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have. When you cast Faerie Fire without a spell slot using this benefit, taking damage can't break your Concentration on the spell.", Sourcebook.LORWYN),
        Feat("shadowmoor_hexer", "Shadowmoor Hexer", "You gain the following benefits. Hex. You always have the Hex spell prepared. Intelligence, Wisdom, or Charisma is your spellcasting ability for this spell (choose when you select this feat). You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast the spell using any spell slots you have. Curse Magic. When a creature that you've cursed with Hex hits you with an attack roll, the creature takes Psychic damage equal to your Proficiency Bonus. A creature takes this damage only once per turn.", Sourcebook.LORWYN),
        Feat("tireless_reveler", "Tireless Reveler", "When an ally you can see within 60 feet of yourself expends Heroic Inspiration, you can gain Heroic Inspiration if you lack it. You can use this benefit a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Short or Long Rest.", Sourcebook.ASTARIONS_BOOK),
        Feat("vampire_hunter", "Vampire Hunter", "You gain the following benefits. Adroit Escape. You have Advantage on checks to escape from nonmagical restraints or the Grappled condition. Vitality Ward. When you take Necrotic damage, you can take a Reaction to mitigate the damage. Roll a number of d6s equal to your Proficiency Bonus, and add them together. Reduce the Necrotic damage you take by this total. Once you use this benefit, you can't use it again until you finish a Short or Long Rest.", Sourcebook.ASTARIONS_BOOK),
        Feat("vampire_s_plaything", "Vampire's Plaything", "You gain the following benefits. Decanting. When you finish a Long Rest, you can create one Potion of Healing or an Antitoxin, as long as you have an empty vial or flask. These liquids evaporate when you finish another Long Rest. Timely Retreat. You can take a Bonus Action to take the Dash action or the Disengage action. You can use this benefit a number of times equal to your Proficiency Bonus, and you recover all expended uses when you finish a Long Rest. Vampiric Connection. The DM determines the fate of your former vampire master. While you and your former vampire master are on the same plane of existence, the vampire can communicate with you telepathically, and you can choose to allow the vampire to perceive through your senses.", Sourcebook.ASTARIONS_BOOK),
        Feat("aberrant_anatomy", "Aberrant Anatomy", "Dark Gift Feat (Prerequisite: Ravenloft Campaign) Exposure to alien horrors like those of the Far Realm has warmed your physical form in supernatural ways. You gain the following features. Breathless. You can hold your breath for 1 hour. Extrasensory Perception. You have proficiency in the Perception skill, if you lack it. You also gain Expertise in that skill. In addition, you have Blindsight with a range of 15 feet. Warping Flesh. Immediately after you make a D20 Test and roll a 1 on the d20, the aberrant influence infecting your form flares, wrenching control of your flesh. Make a Constitution saving throw (DC 13 plus your Proficiency Bonus). On a failed save, you have the Stunned condition until the end of your next turn.", Sourcebook.RAVENLOFT),
        Feat("echoing_soul", "Echoing Soul", "Dark Gift Feat (Prerequisite: Ravenloft Campaign) You experience echoes from a past or alternate life. You gain the following features. Channelled Prowess. You have proficiency in two skills of your choice. In addition, choose one skill you have proficiency in. You gain Expertise in that skill. Whenever you finish a Long Rest you can change your choice of for this benefit. Inherent Tongues. You know one additional language of your choice, which you choose from the language tables in the Player's Handbook. Intrusive Echoes. Immediately after you make a D20 Test and roll a 1 on the d20, memories and sensations from your soul's other life threaten to overtake you. Make a Constitution saving throw (DC 13 plus your Proficiency Bonus). On a failed save, you have the Incapacitated condition until the end of your next turn. While you are Incapacitated in this way, your Speed is halved.", Sourcebook.RAVENLOFT),
        Feat("gathered_whispers", "Gathered Whispers", "Dark Gift Feat (Prerequisite: Ravenloft Campaign) You are haunted by a cacophony of whispering spirits only you can hear. You gain the following features. Spirit Whispers. You learn the Message spell and can cast it without Material components. Additionally, you always have the Augury spell prepared. You can cast it without a spell slot or spell components, and you must finish a Long Rest before you can cast it in this way again. You can also cast the spell using any spell slots you have. Intelligence, Wisdom, or Charisma is your spellcasting ability for this benefit (choose when you select this feat). Unearthly Scream. When you are hit by an attack roll, you can take a Reaction to channel your haunting spirits into a protective, otherworldly scream. You can add your Proficiency Bonus to your AC against that attack, potentially causing it to miss. You can use this benefit a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest. [...]", Sourcebook.RAVENLOFT),
        Feat("living_shadow", "Living Shadow", "Dark Gift Feat (Prerequisite: Ravenloft Campaign) The shadow you cast is animate and ever-present - sometimes it even acts according to its own will. You gain the following features. Grasping Shadow. You learn the Mage Hand spell and can cast it without spell components. Intelligence, Wisdom or Charisma is your spellcasting ability for this spell (choose when you select this feat). Lengthened Strike. When you make a melee attack roll as part of the Attack or Magic action on your turn, you can increase your reach for that attack by 10 feet, as your shadow stretches to aid you. You can use this feature a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest. Ominous Will. Immediately after you make a D20 Test and roll a 1 on the d20, your shadow attempts to exert its will. Make a Wisdom saving throw (DC 13 plus your Proficiency Bonus). [...]", Sourcebook.RAVENLOFT),
        Feat("mist_walker", "Mist Walker", "Dark Gift Feat (Prerequisite: Ravenloft Campaign) You know how to slip through the Mists' grasp, but this freedom comes at a price: If you remain in one area for too long, the Mists find you and drain your life force. You gain the following features. Domain Traveler. When you enter the Mists intent on reaching a specific domain, you are treated as if you possess a Mist talisman keyed to that domain. To use this feature, you must know the name of the domain you have chosen as your destination, but you don't need to have previously visited that land. This trait doesn't allow you to bypass domain borders closed by a Darklord's will. Mist Walk. When you take damage or fail a saving throw to avoid or end the Grappled or Restrained condition, you can take a Reaction and teleport up to 15 feet to an unoccupied space you can see. You can use this feature a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest. Poisoned Roots. [...]", Sourcebook.RAVENLOFT),
        Feat("second_skin", "Second Skin", "Dark Gift Feat (Prerequisite: Ravenloft Campaign) There is another side of you that most people never see: a beast, a terrifying avenger, or a walking nightmare. You gain the following features. Alternate Form. You always have the Alter Self spell prepared. You can cast it without a spell slot or spell components, and you must finish a Long Rest before you can cast it in this way again. You can also cast it using spell slots you have of the appropriate level. Intelligence, Wisdom, or Charisma is your spellcasting ability for this spell (choose when you select this feat). When you cast Alter Self without a spell slot using this feature, it doesn't require Concentration. Involuntary Change. Certain circumstances can involuntarily trigger your transformation. When you select this feat, roll on the Change Catalyst table to determine what triggers your change. [...]", Sourcebook.RAVENLOFT),
        Feat("symbiotic_being", "Symbiotic Being", "Dark Gift Feat (Prerequisite: Ravenloft Campaign) A second being resides within your body, offering knowledge and assistance while furthering its own agenda. You gain the following features. Entwined Existence. The symbiote can't be targeted. If you die, so does your symbiote. If you are returned to life, your symbiote also revives. Second Mind. You gain proficiency in one of the following skills: Arcana, Deception, History, Intimidation, Insight, Investigation, Nature, Religion, Perception, or Persuasion. You also know one additional language of your choice, chosen from the language tables in the Player's Handbook. Sustained Symbiosis. When you fail a saving throw, you can take a Reaction and expend one of your Hit Dice. Roll the die and add the number rolled to the saving throw, potentially turning the failure into a success. You can use this feature a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest. Symbiotic Agenda. [...]", Sourcebook.RAVENLOFT),
        Feat("touch_of_death", "Touch of Death", "Dark Gift Feat (Prerequisite: Ravenloft Campaign) Deathly power resides within you, bursting out at the slightest provocation. You gain the following features. Death Touch. You learn the Chill Touch spell and can cast it without spell components. Necrotic damage you deal with this spell ignores Resistance. Intelligence, Wisdom, or Charisma is your spellcasting ability for this spell (choose when you select this feat). Pull of the Grave. You have Disadvantage on Death Saving Throws.", Sourcebook.RAVENLOFT),
        Feat("watchers", "Watchers", "Dark Gift Feat (Prerequisite: Ravenloft Campaign) Something unnatural is always watching you, taking the form of scurrying vermin and other eerie creatures. You gain the following features. Borrowed Eyes. You always have the Beast Sense and Speak with Animals spells prepared. You can cast each spell without a spell slot, and you must finish a Long Rest before you can cast it in this way again. You can also cast these spells using spell slots you have of the appropriate level. Heightened Suspicion. Whenever you take the Search action, you can roll 1d4 and add the number rolled to any ability check made as part of that action. Incessant Watchers. You have Disadvantage on saving throws made against the Scrying spell. In addition, immediately after you make a D20 Test and roll a 1 on the d20, paranoia threatens to overwhelm you. Make a Wisdom saving throw (DC 13 plus your Proficiency Bonus). On a failed save, you have Disadvantage on D20 Tests for 1 minute. [...]", Sourcebook.RAVENLOFT),
    )

    /** General feats, available in place of an Ability Score Improvement from level 4 on. */
    val GENERAL_FEATS: List<Feat> = listOf(
        Feat("ability_score_improvement", "Ability Score Improvement", "Increase one ability score by 2, or two ability scores by 1 each, to a maximum of 20."),
        Feat("actor", "Actor", "Increase Charisma by 1. You have Advantage on Deception and Performance checks to pass as someone else, and can mimic voices you've heard."),
        Feat("athlete", "Athlete", "Increase Strength or Dexterity by 1. Standing from Prone costs less movement, and you can climb at your normal Speed."),
        Feat("charger", "Charger", "Increase Strength or Dexterity by 1. After a Dash, you can make one attack with a bonus to damage or shove a creature 10 feet."),
        Feat("chef", "Chef", "Increase Constitution or Wisdom by 1. During a rest you can cook food that grants extra hit points or Temporary Hit Points."),
        Feat("crossbow_expert", "Crossbow Expert", "Increase Dexterity by 1. You ignore the Loading property and don't have Disadvantage from being within 5 feet of an enemy."),
        Feat("crusher", "Crusher", "Increase Strength or Constitution by 1. Once per turn when you deal Bludgeoning damage you can push the target 5 feet."),
        Feat("defensive_duelist", "Defensive Duelist", "Increase Dexterity by 1. As a Reaction while wielding a Finesse weapon, add your Proficiency Bonus to your AC against one attack."),
        Feat("dual_wielder", "Dual Wielder", "Increase Strength or Dexterity by 1. You can draw two weapons at once and make an extra attack with a non-Light weapon."),
        Feat("durable", "Durable", "Increase Constitution by 1. When you roll Hit Dice to regain hit points, the minimum result equals twice your Constitution modifier."),
        Feat("elemental_adept", "Elemental Adept", "Increase an ability by 1. Your spells of a chosen damage type ignore Resistance and treat 1s on damage dice as 2s."),
        Feat("fey_touched", "Fey-Touched", "Increase Intelligence, Wisdom, or Charisma by 1. You learn Misty Step and one level 1 Divination or Enchantment spell, castable free once per Long Rest."),
        Feat("grappler", "Grappler", "Increase Strength or Dexterity by 1. You have Advantage on attacks against creatures you have Grappled and can move them more easily."),
        Feat("great_weapon_master", "Great Weapon Master", "Increase Strength by 1. Heavy weapon Critical Hits let you attack again as a Bonus Action, and you can trade accuracy for damage."),
        Feat("heavily_armored", "Heavily Armored", "Increase Strength by 1 and gain training with Heavy armor."),
        Feat("heavy_armor_master", "Heavy Armor Master", "Increase Strength by 1. While in Heavy armor, reduce Bludgeoning, Piercing, and Slashing damage by your Proficiency Bonus."),
        Feat("inspiring_leader", "Inspiring Leader", "Increase Wisdom or Charisma by 1. After a rest you can grant allies Temporary Hit Points."),
        Feat("keen_mind", "Keen Mind", "Increase Intelligence by 1. You can take the Study action as a Bonus Action and always know which way is north."),
        Feat("lightly_armored", "Lightly Armored", "Increase Strength or Dexterity by 1 and gain training with Light armor."),
        Feat("mage_slayer", "Mage Slayer", "Increase Strength or Dexterity by 1. You have Advantage on saves against spells cast within 30 feet and can punish nearby casters."),
        Feat("martial_weapon_training", "Martial Weapon Training", "Increase Strength or Dexterity by 1 and gain proficiency with Martial weapons."),
        Feat("medium_armor_master", "Medium Armor Master", "Increase Strength or Dexterity by 1. Medium armor no longer imposes Stealth Disadvantage and allows a Dex bonus of up to 3."),
        Feat("moderately_armored", "Moderately Armored", "Increase Strength or Dexterity by 1 and gain training with Medium armor and Shields."),
        Feat("mounted_combatant", "Mounted Combatant", "Increase Strength, Dexterity, or Wisdom by 1. You gain Advantage on attacks from a mount and can shield it from damage."),
        Feat("observant", "Observant", "Increase Intelligence or Wisdom by 1. You can take the Search action as a Bonus Action and read lips."),
        Feat("piercer", "Piercer", "Increase Strength or Dexterity by 1. Once per turn reroll a Piercing damage die, and Critical Hits deal an extra die."),
        Feat("poisoner", "Poisoner", "Increase Dexterity or Intelligence by 1. Your poisons ignore Resistance and you can coat a weapon as a Bonus Action."),
        Feat("polearm_master", "Polearm Master", "Increase Strength or Dexterity by 1. You gain a Bonus Action butt-end attack and can strike creatures entering your reach."),
        Feat("resilient", "Resilient", "Increase one ability score by 1 and gain proficiency in saving throws with that ability."),
        Feat("ritual_caster", "Ritual Caster", "Increase Intelligence, Wisdom, or Charisma by 1. You gain a ritual book and can learn ritual spells from a chosen class list."),
        Feat("sentinel", "Sentinel", "Increase Strength or Dexterity by 1. Your Opportunity Attacks reduce a target's Speed to 0, and you can strike foes attacking your allies."),
        Feat("shadow_touched", "Shadow Touched", "Increase Intelligence, Wisdom, or Charisma by 1. You learn Invisibility and one level 1 Illusion or Necromancy spell, castable free once per Long Rest."),
        Feat("sharpshooter", "Sharpshooter", "Increase Dexterity by 1. Your ranged attacks ignore cover, long range doesn't impose Disadvantage, and you can trade accuracy for damage."),
        Feat("shield_master", "Shield Master", "Increase Strength by 1. You can shove with your shield as a Bonus Action and use it to shield yourself from area damage."),
        Feat("skill_expert", "Skill Expert", "Increase one ability score by 1, gain one skill proficiency, and gain Expertise in one skill."),
        Feat("skulker", "Skulker", "Increase Dexterity by 1. You can Hide when only Lightly Obscured, and missing with a ranged attack doesn't reveal you."),
        Feat("slasher", "Slasher", "Increase Strength or Dexterity by 1. Once per turn reduce a target's Speed with Slashing damage, and Critical Hits impose Disadvantage."),
        Feat("speedy", "Speedy", "Increase Dexterity or Constitution by 1. Your Speed increases by 10 feet and Dashing over Difficult Terrain costs no extra movement."),
        Feat("spell_sniper", "Spell Sniper", "Increase Intelligence, Wisdom, or Charisma by 1. Your attack-roll spells gain range and ignore cover, and you learn a cantrip."),
        Feat("telekinetic", "Telekinetic", "Increase Intelligence, Wisdom, or Charisma by 1. You learn Mage Hand and can shove a creature 5 feet as a Bonus Action."),
        Feat("telepathic", "Telepathic", "Increase Intelligence, Wisdom, or Charisma by 1. You can speak telepathically to creatures within 60 feet and cast Detect Thoughts once per Long Rest."),
        Feat("war_caster", "War Caster", "Increase Intelligence, Wisdom, or Charisma by 1. You gain Advantage on Concentration saves and can cast spells as Opportunity Attacks."),
        Feat("weapon_master", "Weapon Master", "Increase Strength or Dexterity by 1 and gain the mastery property of one additional kind of weapon."),

        // ---------------------------------- Eberron: Forge of the Artificer
        // Each Greater feat requires level 4+ and the matching Dragonmark feat.
        Feat("greater_aberrant_mark", "Greater Aberrant Mark", "Requires the Aberrant Dragonmark feat. Increase Constitution by 1. Improved Fortitude: your Aberrant Fortitude rolls 1d6 instead of 1d4 and returns on a Short Rest. Mark of Inspiration: when you cast a cantrip you can expend one or two Hit Point Dice, gaining Temporary Hit Points equal to the roll plus your Constitution modifier while a creature within 30 feet takes that much Force damage, a number of times equal to your Proficiency Bonus per Long Rest.", Sourcebook.EBERRON),
        Feat("greater_mark_of_detection", "Greater Mark of Detection", "Requires the Mark of Detection feat. Increase one ability score by 1. Improved Intuition: Deductive Intuition rolls 1d6 instead of 1d4. Shared Detection: when you cast See Invisibility without a spell slot, a creature you can see within 30 feet also gains the spell's benefits for its duration.", Sourcebook.EBERRON),
        Feat("greater_mark_of_finding", "Greater Mark of Finding", "Requires the Mark of Finding feat. Increase one ability score by 1. Improved Intuition: Hunter's Intuition rolls 1d6 instead of 1d4. Improved Finding: when you cast Hunter's Mark without a spell slot, the spell's range doubles and the target can't benefit from the Invisible condition for the duration.", Sourcebook.EBERRON),
        Feat("greater_mark_of_handling", "Greater Mark of Handling", "Requires the Mark of Handling feat. Increase one ability score by 1. Improved Intuition: Wild Intuition rolls 1d6 instead of 1d4. Improved Handling: while mounted, after you hit a target within 5 feet of your mount, the mount can take a Reaction to move up to its Speed or make one attack. Subdue Animal: as a Magic action, force a Beast or Monstrosity within 30 feet to succeed on a Wisdom save or have the Frightened condition until the start of your next turn, a number of times equal to your Proficiency Bonus per Long Rest.", Sourcebook.EBERRON),
        Feat("greater_mark_of_healing", "Greater Mark of Healing", "Requires the Mark of Healing feat. Increase one ability score by 1. Improved Intuition: Medical Intuition rolls 1d6 instead of 1d4. Improved Healing: you can cast Cure Wounds without a spell slot a number of times equal to your Proficiency Bonus per Long Rest, and you treat any 1 or 2 on its healing dice as a 3.", Sourcebook.EBERRON),
        Feat("greater_mark_of_hospitality", "Greater Mark of Hospitality", "Requires the Mark of Hospitality feat. Increase one ability score by 1. Improved Intuition: Ever Hospitable rolls 1d6 instead of 1d4. Inspired Hospitality: you can modify Purify Food and Drink so that each creature of your choice within 30 feet has its Exhaustion level reduced by 1 and gains Temporary Hit Points equal to your Proficiency Bonus plus your spellcasting modifier, once per Long Rest.", Sourcebook.EBERRON),
        Feat("greater_mark_of_making", "Greater Mark of Making", "Requires the Mark of Making feat. Increase one ability score by 1. Improved Intuition: Artisan's Intuition rolls 1d6 instead of 1d4. Improved Making: when you cast Magic Weapon without a spell slot, you cast it as its level 3 version.", Sourcebook.EBERRON),
        Feat("greater_mark_of_passage", "Greater Mark of Passage", "Requires the Mark of Passage feat. Increase one ability score by 1. Improved Intuition: Intuitive Motion rolls 1d6 instead of 1d4. Inspired Passage: when you cast Misty Step without a spell slot, you can choose up to two willing creatures within 30 feet, each of whom can take a Reaction to teleport up to 30 feet as well.", Sourcebook.EBERRON),
        Feat("greater_mark_of_scribing", "Greater Mark of Scribing", "Requires the Mark of Scribing feat. Increase one ability score by 1. Improved Intuition: Gifted Scribe rolls 1d6 instead of 1d4. Inspired Scribing: you can modify Comprehend Languages to cover up to three willing creatures within 30 feet, and for the duration you and they can communicate telepathically within 1 mile, once per Long Rest.", Sourcebook.EBERRON),
        Feat("greater_mark_of_sentinel", "Greater Mark of Sentinel", "Requires the Mark of Sentinel feat. Increase one ability score by 1. Improved Intuition: Sentinel's Intuition rolls 1d6 instead of 1d4. Improved Sentinel: when you use Vigilant Guardian you can also make one attack with a weapon or an Unarmed Strike as part of that same Reaction.", Sourcebook.EBERRON),
        Feat("greater_mark_of_shadow", "Greater Mark of Shadow", "Requires the Mark of Shadow feat. Increase one ability score by 1. Improved Intuition: Cunning Intuition rolls 1d6 instead of 1d4. Improved Shadow: when you cast Invisibility without a spell slot, you cast it as its level 3 version.", Sourcebook.EBERRON),
        Feat("greater_mark_of_storm", "Greater Mark of Storm", "Requires the Mark of Storm feat. Increase one ability score by 1. Improved Intuition: Windwright's Intuition rolls 1d6 instead of 1d4. Improved Storm: when you cast Gust of Wind without a spell slot, you also gain a Fly Speed of 60 feet for the spell's duration.", Sourcebook.EBERRON),
        Feat("greater_mark_of_warding", "Greater Mark of Warding", "Requires the Mark of Warding feat. Increase one ability score by 1. Improved Intuition: Warder's Intuition rolls 1d6 instead of 1d4. Improved Warding: when a creature makes an attack roll against you or a creature within 30 feet of you, you can take a Reaction to impose Disadvantage on that roll, a number of times equal to your Proficiency Bonus per Long Rest.", Sourcebook.EBERRON),
        Feat("potent_dragonmark", "Potent Dragonmark", "Requires any Dragonmark feat. Increase the spellcasting ability score used by your Dragonmark feat by 1. Dragonmark Preparation: you always have the spells on your Spells of the Mark list prepared. Dragonmark Spellcasting: you gain one extra spell slot of a level equal to half your level (round up, maximum level 5), regained on a Short or Long Rest, usable only for spells your Dragonmark feat grants.", Sourcebook.EBERRON),

        // ---------------------------------- Forgotten Realms: Heroes of Faerûn
        Feat("cold_caster", "Cold Caster", "Increase Intelligence, Wisdom, or Charisma by 1. Cantrip: you learn Ray of Frost, or a different Wizard cantrip if you already know it. Frostbite: once per turn when you hit a creature and deal Cold damage, the creature subtracts 1d4 from the next saving throw it makes before the end of your next turn.", Sourcebook.HEROES_OF_FAERUN),
        Feat("dragonscarred", "Dragonscarred", "Requires the Cult of the Dragon Initiate feat. Increase Constitution or Charisma by 1. Damage Resistance: choose Acid, Cold, Fire, Lightning, or Poison; you have Resistance to it. Fearsome Power: when you deal damage as part of the Attack or Magic action on your turn, you can use Dragon's Terror as a Bonus Action that turn.", Sourcebook.HEROES_OF_FAERUN),
        Feat("enclave_magic", "Enclave Magic", "Requires the Emerald Enclave Fledgling feat. Increase Intelligence, Wisdom, or Charisma by 1. Friend to Animals: you have Advantage on ability checks when taking the Influence action with Beasts. Two Hearts, One Mind: you always have Beast Sense prepared, can cast it once without a spell slot per Long Rest without Concentration, and can also cast it with slots.", Sourcebook.HEROES_OF_FAERUN),
        Feat("fairy_trickster", "Fairy Trickster", "Increase Dexterity or Charisma by 1. Faerie Trod Trotter: when you take the Disengage action, Difficult Terrain costs you no extra movement for the rest of that turn. Flustering Strike: when you hit a creature you can force a Wisdom saving throw (DC 8 plus this feat's ability modifier and your Proficiency Bonus) or it has Disadvantage on saving throws until the end of your next turn, a number of times equal to your Proficiency Bonus per Long Rest.", Sourcebook.HEROES_OF_FAERUN),
        Feat("genie_magic", "Genie Magic", "Increase Intelligence, Wisdom, or Charisma by 1. Wish Magic: as a Magic action you can cast a level 1 spell of your choice from the Sorcerer spell list that has a casting time of an action, once per Long Rest. At level 11 you cast it as though using a level 2 slot, and at level 17 a level 3 slot.", Sourcebook.HEROES_OF_FAERUN),
        Feat("harper_teamwork", "Harper Teamwork", "Requires the Harper Agent feat. Increase Dexterity or Charisma by 1. Withering Wordplay: when you take the Help action to assist an ally's attack roll against an enemy, that enemy also has Disadvantage on the first saving throw it makes before the start of your next turn. Inspiring Willpower: if you succeed on a save to end the Frightened or Paralyzed condition on yourself, you can end the same condition on one ally within 30 feet.", Sourcebook.HEROES_OF_FAERUN),
        Feat("lordly_resolve", "Lordly Resolve", "Requires the Lords' Alliance Agent feat. Increase Strength or Charisma by 1. Standard Bearer: as a Bonus Action, choose up to three creatures within 60 feet that can see you; each can take a Reaction to right itself and end the Prone condition, and each is bolstered for 1 minute so it can't be possessed or gain the Charmed or Frightened condition. Once per Long Rest.", Sourcebook.HEROES_OF_FAERUN),
        Feat("mythal_touched", "Mythal Touched", "Increase Intelligence, Wisdom, or Charisma by 1. Mythal Ward: if a spell attack hits you or you fail a saving throw against a spell, you can take a Reaction to roll on the Mythal-Touched Magic table, producing an effect ranging from a Force explosion to a telepathic link, reversed gravity, a Stunned attacker, a +2 bonus to your AC, or dissipating the triggering spell entirely. You can do this a number of times equal to your Proficiency Bonus per Long Rest.", Sourcebook.HEROES_OF_FAERUN),
        Feat("orders_resilience", "Order's Resilience", "Requires the Tyro of the Gauntlet feat. Increase Strength, Wisdom, or Charisma by 1. Resurge: when you have the Prone condition you can right yourself with only 5 feet of movement. Stronger Together: while you are within 5 feet of an ally that doesn't have the Incapacitated condition, you and that ally have Advantage on Strength saving throws.", Sourcebook.HEROES_OF_FAERUN),
        Feat("purple_dragon_commandant", "Purple Dragon Commandant", "Requires the Purple Dragon Rook feat and Martial Weapon proficiency. Increase Strength or Dexterity by 1. Encourage Ally: as a Bonus Action you bolster one ally within 30 feet, granting Temporary Hit Points equal to 2d6 plus this feat's ability modifier, a number of times equal to your Proficiency Bonus per Long Rest. Last Stand: you have Advantage on attack rolls while Bloodied.", Sourcebook.HEROES_OF_FAERUN),
        Feat("spellfire_adept", "Spellfire Adept", "Requires the Spellfire Spark feat or the Spellcasting or Pact Magic feature. Increase Intelligence, Wisdom, or Charisma by 1. Fueled Spellfire: once per turn, when a spell you cast deals Radiant damage, you can expend up to two Hit Point Dice and add the total to one damage roll of the spell. Searing Spellfire: your Radiant damage rolls ignore Resistance to Radiant damage.", Sourcebook.HEROES_OF_FAERUN),
        Feat("street_justice", "Street Justice", "Increase Strength or Dexterity by 1. Headlock: your allies have Advantage on attack rolls against a creature you have Grappled. Sturdy Knot: when you use a Chain, Manacles, or Rope to bind a creature, add your Proficiency Bonus to the DC to escape or burst it. Tough Talk: a creature's Hostile attitude doesn't impose Disadvantage on your Charisma (Intimidation) checks to influence it.", Sourcebook.HEROES_OF_FAERUN),
        Feat("zhentarim_tactics", "Zhentarim Tactics", "Requires the Zhentarim Ruffian feat. Increase Dexterity or Charisma by 1. Retaliate: immediately after a creature within 5 feet hits you with a melee attack, you can make an Opportunity Attack against it. Versatile Merc: when you finish a Long Rest, choose a skill you're proficient in; you have Expertise in it until your next Long Rest.", Sourcebook.HEROES_OF_FAERUN),

        // ---------------------------------- Path of the Death Knight
        // The path opens at level 4, in place of an Ability Score Improvement — these are
        // not Origin feats, and a level 1 character can't start down either path.
        Feat("death_knight_initiate", "Death Knight Initiate", "Path of the Death Knight. Requires level 4+ and the Weapon Mastery feature. Increase your Strength or Charisma score by 1, to a maximum of 20. Death Points: you have a number of Death Points equal to your Proficiency Bonus, regaining all expended points when you finish a Long Rest. Dread Strike: you always have the Wrathful Smite spell prepared, with Charisma as your spellcasting ability. You can cast it without a spell slot by expending 1 Death Point, and when you do, the target has Disadvantage on Wisdom saving throws to avoid or end the spell's effect. You can also cast it using any spell slots you have.", Sourcebook.UA_VILLAINOUS),
        Feat("dread_authority", "Dread Authority", "Path of the Death Knight. Requires the Death Knight Initiate feat. Increase your Constitution or Charisma score by 1, to a maximum of 20. Dread Command: you always have the Command spell prepared, with Charisma as your spellcasting ability. You can cast it without a spell slot by expending 1 Death Point, and you can also cast it using any spell slots you have. When you expend Death Points to cast Command, Undead targeted by it have Disadvantage on the saving throw against the spell.", Sourcebook.UA_VILLAINOUS),
        Feat("harbinger_of_doom", "Harbinger of Doom", "Path of the Death Knight. Requires the Death Knight Initiate feat. Increase your Strength, Constitution, or Charisma score by 1, to a maximum of 20. Ill Omen: you always have the Bane spell prepared, with Charisma as your spellcasting ability. You can cast it without a spell slot by expending 1 Death Point, and you can also cast it using any spell slots you have. When you expend Death Points to cast Bane, affected targets subtract 1d6 from attack rolls and saving throws instead of 1d4.", Sourcebook.UA_VILLAINOUS),
        Feat("deathly_presence", "Deathly Presence", "Path of the Death Knight. Requires level 8+ and the Death Knight Initiate feat. Increase your Strength, Constitution, or Charisma score by 1, to a maximum of 20. Awful Presence: you always have the Fear spell prepared, with Charisma as your spellcasting ability. You can cast it without a spell slot by expending 1 Death Point, and you can also cast it using any spell slots you have. When you expend Death Points to cast Fear, you deal 7 (2d6) Psychic damage to each creature that fails its saving throw against the spell, in addition to the spell's normal effects.", Sourcebook.UA_VILLAINOUS),
        Feat("unholy_steed", "Unholy Steed", "Path of the Death Knight. Requires level 8+ and the Death Knight Initiate feat. Increase your Strength or Constitution score by 1, to a maximum of 20. Spectral Steed: you always have the Find Steed spell prepared, with Charisma as your spellcasting ability. You can cast it without a spell slot by expending 1 Death Point, and you can also cast it using any spell slots you have. When you expend Death Points to cast Find Steed, the summoned steed is a Fiend, and targets you choose have Disadvantage on the Wisdom saving throw against its Fell Glare.", Sourcebook.UA_VILLAINOUS),
        Feat("death_knight_ascension", "Death Knight Ascension", "Path of the Death Knight. Requires level 12+ and two other Path of the Death Knight feats. Increase your Strength or Charisma score by 1, to a maximum of 20. Undead: your creature type is Undead. Unholy Anatomy: you have Resistance to Necrotic and Poison damage, and you don't gain Exhaustion levels from dehydration, malnutrition, or suffocation. Hellfire Orb: as a Magic action you can expend 1 to 5 Death Points to throw an orb of pure hellfire at a point you can see within 120 feet. Each creature in a 20-foot-radius Sphere centered on that point makes a Dexterity saving throw (DC 8 plus your Charisma modifier and Proficiency Bonus), taking 2d6 Fire damage and 2d6 Necrotic damage per Death Point expended on a failed save, or half as much on a success.", Sourcebook.UA_VILLAINOUS),

        // ---------------------------------- Path of the Lich
        Feat("lich_initiate", "Lich Initiate", "Path of the Lich. Requires level 4+ and the Spellcasting or Pact Magic feature. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Creating Your Spirit Jar: choose a Tiny object of great significance to you and spend a Long Rest anchoring your soul to it, allowing you to consume the souls of the living to bolster your own power. You can have only one spirit jar at a time; creating a second destroys the old one. Its Armor Class equals your spell save DC and it has Hit Points equal to your spellcasting ability modifier plus your character level. If it is destroyed you gain 2 Exhaustion levels and can't use Soul Siphon until you create a new one. Soul Siphon: when you reduce a Humanoid enemy to 0 Hit Points, you can consume its soul (no action required); on your next turn, the first creature you hit with an attack takes extra Necrotic damage equal to 1d6 plus your spellcasting ability modifier. You also gain this benefit if someone else reduces a Humanoid enemy within 10 feet of you to 0 Hit Points. A soul consumed this way can be restored only by a True Resurrection or Wish spell.", Sourcebook.UA_VILLAINOUS),
        Feat("arcane_restoration", "Arcane Restoration", "Path of the Lich. Requires the Lich Initiate feat. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Essence Rejuvenation: when you use Soul Siphon to consume a soul, you can choose one or more expended spell slots to recover. The spell slots can have a combined level of no more than 4. Once you use this feature you can't use it again until you finish a Short or Long Rest.", Sourcebook.UA_VILLAINOUS),
        Feat("transfer_life", "Transfer Life", "Path of the Lich. Requires the Lich Initiate feat. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Soul Transference: when you use Soul Siphon to consume a soul, you can choose a creature within 60 feet of yourself to gain Temporary Hit Points equal to your Proficiency Bonus plus your spellcasting ability modifier (minimum of 1 Temporary Hit Point).", Sourcebook.UA_VILLAINOUS),
        Feat("undead_grasp", "Undead Grasp", "Path of the Lich. Requires the Lich Initiate feat. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Paralyzing Touch: you know the Chill Touch cantrip; if you already know it, you learn another cantrip of your choice. Intelligence, Wisdom, or Charisma is your spellcasting ability for this spell (choose when you select this feat). When you deal damage with Chill Touch, you can expend a level 1+ spell slot to attempt to paralyze the target. The target takes an extra 1d10 Necrotic damage per level of the spell slot expended and must succeed on a Constitution saving throw against your spell save DC or have the Paralyzed condition until the start of your next turn.", Sourcebook.UA_VILLAINOUS),
        Feat("lich_ascension", "Lich Ascension", "Path of the Lich. Requires level 12+ and at least two other Path of the Lich feats. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Undead: your creature type is Undead. Unholy Anatomy: you have Resistance to Necrotic and Poison damage, and you don't gain Exhaustion levels from dehydration, malnutrition, or suffocation. Frightening Gaze: you learn the Fear spell if you don't already know it, and you always have it prepared. Intelligence, Wisdom, or Charisma is your spellcasting ability for this spell (choose when you select this feat). You can cast it without expending a spell slot a number of times equal to your spellcasting ability modifier (minimum of once), regaining all expended uses when you finish a Long Rest. Rejuvenation: if you die, you re-form in 1d10 days if you have a spirit jar and aren't revived before then, gaining a new body with all your Hit Points in the nearest unoccupied space within 5 feet of your spirit jar.", Sourcebook.UA_VILLAINOUS),

        // ---------------------------------- Imported general feats and Planar Pacts
        Feat("shifting_combatant", "Shifting Combatant", "General Feat (Prerequisite: Level 4+, Weapon Mastery Feature) You gain the following benefits. Ability Score Increase. Increase your Strength or Dexterity score by 1, to a maximum of 20. Domino Strike. When you hit a creature with a weapon and activate the Push mastery property to push that creature into a space occupied by a Large or smaller creature, you can force the creatures to collide. Each creature makes a Dexterity saving throw (DC 8 plus the ability modifier of the score increased by this feat and your Proficiency Bonus), taking 1d10 Bludgeoning damage on a failed save. Fearless Leap. When you make a Long Jump, moving at least 10 feet immediately before the jump, and land in a space within 5 feet of two or more enemies, attack rolls made against you have Disadvantage until the start of your next turn.", Sourcebook.DDB_DROPS),
        Feat("tactical_combatant", "Tactical Combatant", "General Feat (Prerequisite: Level 4+ and Strength or Dexterity 13+) You gain the following benefits. Ability Score Increase. Increase your Strength or Dexterity score by 1, to a maximum of 20. Buffering Strike. When you hit a creature with a weapon, you can gain Temporary Hit Points equal to the total number rolled on the weapon's damage dice. Once you use this benefit, you can't use it again until you roll Initiative or finish a Short or Long Rest. Honed Instincts. When you fail an ability check, you can roll 1d6 and add the number rolled to the ability check, potentially turning it into a success. Once you use this benefit, you can't use it again until you roll Initiative or finish a Short or Long Rest.", Sourcebook.DDB_DROPS),
        Feat("bloodlust", "Bloodlust", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase your Strength, Dexterity, or Constitution score by 1, to a maximum of 20. Powerful Recovery. When you roll a Hit Point Die to regain Hit Points, you can treat any roll of 1 or 2 as a 3. Sanguine Feast. Once per turn when you hit a Bloodied creature that isn't a Construct or Undead with an attack roll, you can expend a Hit Point Die, roll it, and regain a number of Hit Points equal to the number rolled plus your Constitution modifier. You can use this feature a number of times equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest.", Sourcebook.ASTARIONS_BOOK),
        Feat("bomber", "Bomber", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase your Dexterity score by 1, to a maximum of 20. Far Lobber. When you use the Attack action to throw a vial or flask, you can target an object or creature you can see within 40 feet of yourself. Long Shots. Attacking at long range doesn't impose Disadvantage on your attack rolls with Thrown weapons.", Sourcebook.ASTARIONS_BOOK),
        Feat("cloying_mists", "Cloying Mists", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Arise, Fog. You always have the Fog Cloud spell prepared. You can cast it without a spell slot, and you must finish a Long Rest before you can cast it in this way again. You can also cast it using spell slots you have of the appropriate level. Your spellcasting ability for the spell is the ability increased by this feat. Grasping Mist. Whenever you cast Fog Cloud , nonmagical flames in the spell's Sphere are extinguished, and creatures other than you and your allies have their Speed reduced by 5 feet while in the spell's Sphere.", Sourcebook.ASTARIONS_BOOK),
        Feat("delicious_pain", "Delicious Pain", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase one ability score of your choice by 1, to a maximum of 20. Toughened Flesh. Immediately after you take Bludgeoning, Piercing, or Slashing damage, you can take a Reaction to gain Resistance to Bludgeoning, Piercing, and Slashing damage until the start of your next turn. Once you use this benefit, you can't use it again until you finish a Short or Long Rest.", Sourcebook.ASTARIONS_BOOK),
        Feat("light_bringer", "Light Bringer", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Sacred Magic. You learn the Light spell and can cast it without Material components. If you already know that cantrip, you learn a different Cleric cantrip of your choice. The spell's spellcasting ability is the ability increased by this feat. Solar Luminance. When you cast Light , you can have the light from the spell be sunlight. Once you use this benefit, you can't use it again until you finish a Long Rest. Sun's Healing. As a Bonus Action while within sunlight, you can expend one of your Hit Point Dice, roll the die, and regain a number of Hit Points equal to the roll. Once you use this benefit, you can't use it again until you finish a Short or Long Rest.", Sourcebook.ASTARIONS_BOOK),
        Feat("love_bites", "Love Bites", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase one ability score of your choice by 1, to a maximum of 20. Endearing Pain. Immediately after you damage a creature with a Melee weapon or an Unarmed Strike, you can take a Bonus Action to give the target the Charmed condition until the start of your next turn or until you or your allies damage it. Once you use this benefit, you can't use it again until you finish a Short or Long Rest.", Sourcebook.ASTARIONS_BOOK),
        Feat("putrefy", "Putrefy", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase one ability score of your choice by 1, to a maximum of 20. Necrosis. When you make a damage roll that deals Necrotic damage, you can cause one creature taking that damage to have the Poisoned condition until the start of your next turn. Once you use this benefit, you can't use it again until you finish a Short or Long Rest.", Sourcebook.ASTARIONS_BOOK),
        Feat("rebuke", "Rebuke", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase one ability score of your choice by 1, to a maximum of 20. Radiant Strike. When you make a damage roll that deals Radiant damage, you can cause one Huge or smaller creature taking the damage to have the Prone condition. Once you use this benefit, you can't use it again until you finish a Short or Long Rest.", Sourcebook.ASTARIONS_BOOK),
        Feat("treacherous_allure", "Treacherous Allure", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Enchanting Presence. You always have the Charm Person spell prepared. You can cast it without a spell slot, and you must finish a Long Rest before you can cast it in this way again. You can also cast it using spell slots you have of the appropriate level. Your spellcasting ability for the spell is the ability increased by this feat. Inevitable Betrayal. You have Advantage on attack rolls against creatures with the Charmed condition.", Sourcebook.ASTARIONS_BOOK),
        Feat("vampire_touched", "Vampire Touched", "General Feat (Prerequisite: Level 4+) You gain the following benefits. Ability Score Increase. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Vampire Magic. Choose one level 1 spell from the Enchantment or Illusion school of magic. You always have that spell and the Spider Climb spell prepared. You can cast each of these spells without expending a spell slot, but when you cast Spider Climb this way, you must target yourself, and you must finish a Long Rest before you can cast each spell in this way again. You can also cast either spell using spell slots you have of the appropriate level. Your spellcasting ability for the spells is the ability increased by this feat.", Sourcebook.ASTARIONS_BOOK),
        Feat("fey_pact", "Fey Pact", "Planar Pact Feat (Prerequisite: Can't Have Another Planar Pact Feat) You gain the following benefits. Fey Bond. You know Sylvan. If you already know Sylvan when you select this feat, you instead learn one language of your choice from the language tables in the Player's Handbook. You also gain Proficiency in the Nature skill. Fey Cantrips. You know the Druidcraft cantrip and learn one other cantrip of your choice from the Divination or Enchantment school of magic. Intelligence, Wisdom, or Charisma is your spellcasting ability for these spells (choose when you select this feat). Honeyed Words. When you fail a Charisma (Deception or Persuasion) check, you can reroll the check, and you must use the new roll. Once this benefit turns a failure into a success, you can't use it again until you finish a Long Rest.", Sourcebook.DDB_DROPS),
        Feat("infernal_pact", "Infernal Pact", "Planar Pact Feat (Prerequisite: Can't Have Another Planar Pact Feat) You gain the following benefits. Infernal Resistance. You have Resistance to Fire damage or Poison damage. Infernal Sight. You gain Darkvision with a range of 30 feet. This Darkvision is unimpeded by magical Darkness. Silver-Tongued. You gain proficiency in the Deception skill.", Sourcebook.DDB_DROPS),
        Feat("fey_sentinel", "Fey Sentinel", "General Feat (Prerequisite: Level 4+, Fey Pact Feat) You gain the following benefits. Ability Score Increase. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Fading Target. When an enemy misses you with an attack roll, you can take a Reaction to gain the Invisible condition until the start of your next turn or until immediately after you make an attack roll, deal damage, or cast a spell. Once you use this benefit, you can't do so again until you finish a Long Rest. Fey Shift. When you take the Dash action, you can forgo the extra movement to teleport to an unoccupied space you can see within a distance equal to half your Speed instead. Nature's Roots. You always have the Entangle spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast it using any spell slots you have. The spell's spellcasting ability is the ability increased by this feat. [...]", Sourcebook.DDB_DROPS),
        Feat("fey_tormentor", "Fey Tormentor", "General Feat (Prerequisite: Level 4+, Fey Pact Feat)) You gain the following benefits. Ability Score Increase. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 20. Faerie Time Warp. As a Bonus Action, choose up to three creatures you can see within 60 feet of yourself. Each target makes a Wisdom saving throw (DC 8 plus the ability modifier of the score increased by this feat and your Proficiency Bonus). On a failed save, the target's Speed is reduced by 10 feet, and it takes a −2 penalty to AC until the end of your next turn. Once you use this benefit, you can't use it again until you finish a Long Rest. Hag's Hex. You always have the Hex spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. You can also cast it using any spell slots you have. The spell's spellcasting ability is the ability increased by this feat. [...]", Sourcebook.DDB_DROPS),
        Feat("infernal_bulwark", "Infernal Bulwark", "General Feat (Prerequisite: Level 4+, Infernal Pact Feat) You gain the following benefits. Ability Score Increase. Increase your Constitution or Charisma score by 1, to a maximum of 20. Devil's Flesh. Your skin thickens and assumes a scaled, leathery texture. While you aren't wearing armor or wielding a Shield, your base Armor Class equals 10 plus your Dexterity modifier plus the modifier of the ability increased by this feat. Infernal Protection. You always have the Armor of Agathys spell prepared. You can cast it once without a spell slot, and you regain the ability to cast it in that way when you finish a Long Rest. When you cast it without a spell slot using this feature, you cast this spell as its level 2 version, and it deals Fire damage instead of Cold damage. You can also cast the spell using any spell slots you have of the appropriate level. Charisma is your spellcasting ability for this spell. Vengeful Surge. [...]", Sourcebook.DDB_DROPS),
        Feat("infernal_dragoon", "Infernal Dragoon", "General Feat (Prerequisite: Level 4+, Infernal Pact Feat) Ability Score Increase. Increase your Constitution or Charisma score by 1, to a maximum of 20. Devilish Aura. Your close association with diabolic powers unsettles others. You can take a Magic action to manifest an aura of fear in a 30-foot Emanation originating from yourself. Each creature of your choice in that area makes a Charisma saving throw (DC 8 plus the modifier of the ability increased by this feat plus your Proficiency Bonus). On a failed save, it has the Frightened condition until the end of its next turn. On a successful save, a creature is unaffected, and it is immune to this ability for 24 hours. Devil's Favor. You can call on your infernal patron to aid you. When you make a D20 Test, you can add a +2 bonus to the roll. Once you use this benefit, you can't do so again until you finish a Long Rest. Diabolic Empowerment. You always have the Magic Weapon spell prepared. [...]", Sourcebook.DDB_DROPS),
    )

    /** Epic Boon feats, taken at level 19. */
    val EPIC_BOONS: List<Feat> = listOf(
        Feat("boon_combat_prowess", "Boon of Combat Prowess", "Increase one ability score by 1. Once per turn, turn a miss into a hit."),
        Feat("boon_dimensional_travel", "Boon of Dimensional Travel", "Increase one ability score by 1. After taking the Attack or Magic action, you can teleport up to 30 feet."),
        Feat("boon_energy_resistance", "Boon of Energy Resistance", "Increase one ability score by 1. Gain Resistance to two damage types and the ability to ignore Resistance."),
        Feat("boon_fate", "Boon of Fate", "Increase one ability score by 1. Add 2d4 to another creature's d20 Test once per Long Rest."),
        Feat("boon_fortitude", "Boon of Fortitude", "Increase one ability score by 1. Your hit point maximum increases by 40, and healing yourself restores extra hit points."),
        Feat("boon_irresistible_offense", "Boon of Irresistible Offense", "Increase Strength or Dexterity by 1. Your attacks ignore Resistance, and a natural 20 deals extra damage."),
        Feat("boon_recovery", "Boon of Recovery", "Increase one ability score by 1. Heal for half your hit point maximum as a Bonus Action once per Long Rest."),
        Feat("boon_skill", "Boon of Skill", "Increase one ability score by 1. Gain proficiency in all skills and Expertise in one of your choice."),
        Feat("boon_speed", "Boon of Speed", "Increase one ability score by 1. Your Speed increases by 30 feet and you can Disengage as a Bonus Action."),
        Feat("boon_night_spirit", "Boon of the Night Spirit", "Increase one ability score by 1. In Dim Light or Darkness you become Invisible and deal extra Psychic damage."),
        Feat("boon_truesight", "Boon of Truesight", "Increase one ability score by 1. You gain Truesight out to 60 feet."),

        // ---------------------------------- Eberron: Forge of the Artificer
        Feat("boon_of_siberys", "Boon of Siberys", "Requires an Eberron campaign. Increase one ability score by 1, to a maximum of 30. Aberrant Magic: choose a level 8 or lower spell from the Sorcerer spell list, or one from the Siberys Dragonmark Spells table — Animal Shapes, Control Weather, Demiplane, Heroes' Feast, Maze, Mind Blank, Plane Shift, Project Image, Regenerate, Symbol, Teleport, or True Seeing. You always have it prepared, can cast it free without components once per Short or Long Rest, and can also cast it with any slots of the appropriate level.", Sourcebook.EBERRON),

        // ---------------------------------- Forgotten Realms: Heroes of Faerûn
        Feat("boon_of_bloodshed", "Boon of Bloodshed", "Increase one ability score by 1, to a maximum of 30. Killer's Fortune: when an enemy you can see is reduced to 0 Hit Points, you gain Advantage on the next attack roll you make before the end of your next turn. Power from Pain: once per turn, when you make an attack roll while Bloodied, you can deal extra damage to the target equal to your Proficiency Bonus, of the same type as the attack's.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_bountiful_health", "Boon of Bountiful Health", "Increase one ability score by 1, to a maximum of 30. Augmented Health: whenever you gain Temporary Hit Points, increase the number you gain by 5. Superior Recuperation: when you spend one or more Hit Point Dice to regain Hit Points, you can instead use the highest number possible for each die.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_communication", "Boon of Communication", "Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 30. Cunning Speaker: you don't have Disadvantage on ability checks to influence Hostile creatures. Gifted Interpreter: you understand the literal meaning of any language you hear or see signed, and of any written language you see. Mental Communication: you gain telepathy with a range of 120 feet.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_desperate_resilience", "Boon of Desperate Resilience", "Increase Strength or Constitution by 1, to a maximum of 30. Defense of Body and Mind: while you are Bloodied, you have Resistance to every damage type except Force.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_exquisite_radiance", "Boon of Exquisite Radiance", "Increase one ability score by 1, to a maximum of 30. Eternal Rest: creatures you reduce to 0 Hit Points can't become Undead. Powerful Radiance: when you make a damage roll that deals Radiant damage, you can instead use the highest number possible for each damage die, once per Long Rest.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_fluid_forms", "Boon of Fluid Forms", "Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 30. Shapechanger: as a Magic action you can shape-shift into a Beast, Humanoid, or Monstrosity with a Challenge Rating of 10 or lower for 1 hour, gaining Temporary Hit Points equal to the form's Hit Points, once per Long Rest. Hardy Transformation: increase those Temporary Hit Points by 20.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_fortunes_favor", "Boon of Fortune's Favor", "Increase one ability score by 1, to a maximum of 30. Saving Throw Reroll: when you fail a saving throw you can reroll it and must use the new roll. Once you use this benefit you can't do so again until the start of your next turn.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_poison_mastery", "Boon of Poison Mastery", "Increase one ability score by 1, to a maximum of 30. Antitoxic: you have Immunity to Poison damage and to the Poisoned condition. Perfect Poisoner: once per turn, when you roll dice to determine Poison damage a creature takes from your attack, spell, or feature, you can instead use the highest number possible for each die.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_revelry", "Boon of Revelry", "Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 30. Inspire Dance: you always have Otto's Irresistible Dance prepared, can cast it once without a spell slot per Long Rest, and casting it requires no components and can't have its Concentration broken by damage. Sing Out: a creature Charmed by that spell can't cast spells with Verbal components and sings delightful nonsense if it can sing.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_terror", "Boon of Terror", "Increase Charisma by 1, to a maximum of 30. Fearless: you have Immunity to the Frightened condition. Flee, Fools! When a Frightened creature starts its turn within 60 feet of you and isn't behind Total Cover, you can take a Reaction to force a Wisdom saving throw (DC 8 plus your Charisma modifier and Proficiency Bonus) or it spends its turn moving away from you, once per Short or Long Rest. Intimidating: you gain proficiency and Expertise in Intimidation.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_the_bright_sun", "Boon of the Bright Sun", "Increase Constitution, Wisdom, or Charisma by 1, to a maximum of 30. Daylight Presence: as a Bonus Action you radiate a 30-foot Emanation of Bright Light that is sunlight and dispels overlapping magical Darkness, lasting until you dismiss it, die, or have the Incapacitated condition. Fortifying Light: while it is active, you and allies you can see within it gain 10 Temporary Hit Points at the start of each of your turns.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_the_furious_storm", "Boon of the Furious Storm", "Requires the Spellcasting or Pact Magic feature. Increase Intelligence, Wisdom, or Charisma by 1, to a maximum of 30. Eye of the Storm: you have Resistance to Lightning and Thunder damage, and Immunity to both while Bloodied. Storm's Strength: creatures have Disadvantage on saving throws against your spells that deal Lightning or Thunder damage.", Sourcebook.HEROES_OF_FAERUN),
        Feat("boon_of_the_soul_drinker", "Boon of the Soul Drinker", "Increase one ability score by 1, to a maximum of 30. Grave Resistance: you have Resistance to Cold damage and Necrotic damage. Siphon Life: when an enemy within 120 feet of you is reduced to 0 Hit Points, you can take a Reaction to regain 50 Hit Points, once per Short or Long Rest.", Sourcebook.HEROES_OF_FAERUN),

        // ---------------------------------- Unearthed Arcana 2026: Villainous Options
        Feat("boon_of_the_bandit_king", "Boon of the Bandit King", "Increase one ability score by 1, to a maximum of 30. Dastardly Charm: you have Advantage on Dexterity (Sleight of Hand) checks to pick a pocket. When you succeed on such a check, you can cause the target of your theft to willingly part with the item and have the Charmed condition for 1 minute or until it takes damage; once you use this benefit you can't use it again until you finish a Short or Long Rest. Uncatchable: you don't provoke Opportunity Attacks when you move out of a creature's reach.", Sourcebook.UA_VILLAINOUS),
        Feat("boon_of_the_cleansed_heart", "Boon of the Cleansed Heart", "Increase one ability score by 1, to a maximum of 30. Cleanse Heart: you can cast Dispel Evil and Good without expending a spell slot, though you can't use the spell's Dismissal special function when you cast it this way. Radiant Reflection: you have Immunity to Necrotic damage, and when you would be subjected to Necrotic damage and don't have the Incapacitated condition, you can deal 2d8 Radiant damage to each creature of your choice within a 10-foot Emanation originating from yourself.", Sourcebook.UA_VILLAINOUS),
        Feat("boon_of_the_hunters_eye", "Boon of the Hunter's Eye", "Increase one ability score by 1, to a maximum of 30. Quick Capture: when you deal damage to a creature you intend to knock out rather than kill, if the target has 20 or fewer Hit Points after your damage is dealt, the target is reduced to 0 Hit Points instead. Studied Hunter: when you roll Initiative, you can choose a creature you can see; you know whether that creature has any Immunities, Resistances, or Vulnerabilities, and if the creature has any, you know what they are.", Sourcebook.UA_VILLAINOUS),
        Feat("boon_of_unwavering_devotion", "Boon of Unwavering Devotion", "Increase one ability score by 1, to a maximum of 30. Possession Immunity: you automatically succeed on saving throws to avoid or end possession. See Through Illusions: visual illusions appear transparent to you, and you automatically succeed on saving throws against them. Undeniable Confidence: immediately after a creature you can see succeeds on a Wisdom saving throw against an effect you created, you can take a Reaction to force that creature to reroll the save, and it must use the new roll. Once you use it you can't use it again until you roll Initiative or finish a Short or Long Rest.", Sourcebook.UA_VILLAINOUS),

        // ---------------------------------- Imported epic boons
        Feat("boon_of_spell_recall", "Boon of Spell Recall", "Prerequisite: Level 19+ You gain the following benefits. Ability Score Increase. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 30. Free Casting. Whenever you cast a spell with a level 1-4 spell slot, roll 1d4. If the number you roll is the same as the slot's level, the slot isn't expended."),
        Feat("boon_of_blazing_dawn", "Boon of Blazing Dawn", "Epic Boon Feat (Prerequisite: Level 19+) You gain the following benefits. Ability Score Increase. Increase one ability score of your choice by 1, to a maximum of 30. Beloved of the Sun. You have Immunity to Radiant damage. Blazing Strike. When you hit a creature with a weapon attack, the damage can be Radiant or the weapon's normal damage type (your choice). Burst of Sunlight. Once per turn when you hit a creature with an attack that deals Radiant damage, you can emit Bright Light in a 30-foot radius from yourself and Dim Light for an additional 30 feet until the start of your next turn. This light is sunlight.", Sourcebook.ASTARIONS_BOOK),
        Feat("boon_of_looming_shadows", "Boon of Looming Shadows", "Epic Boon Feat (Prerequisite: Level 19+) You gain the following benefits. Ability Score Increase. Increase one ability score of your choice by 1, to a maximum of 30. Shadowy Stretch. When you take the Attack action, your reach for your Melee weapon attacks increases by 10 feet until the end of your turn. Dancing Silhouette. You can take the Dodge action as a Bonus Action.", Sourcebook.ASTARIONS_BOOK),
        Feat("boon_of_misty_escape", "Boon of Misty Escape", "Epic Boon Feat (Prerequisite: Level 19+) You gain the following benefits. Ability Score Increase. Increase your Intelligence, Wisdom, or Charisma score by 1, to a maximum of 30. Gaseous Form. If you drop to 0 Hit Points but aren't killed outright, you can instead drop to 1 Hit Point and cast Gaseous Form without expending a spell slot (no action required). When you cast this spell this way, you can target only yourself, your Fly Speed is 20 feet, and you regain 10 Hit Points at the start of each of your turns for the spell's duration. The spell's spellcasting ability is the ability increased by this feat. Once you use this benefit, you can't do so again until you finish a Long Rest.", Sourcebook.ASTARIONS_BOOK),
    )

    val ALL: List<Feat> = ORIGIN_FEATS + GENERAL_FEATS + EPIC_BOONS

    fun byId(id: String): Feat? = ALL.find { it.id == id }
}
